import json
units=[
('Jag och familjen','ez|jag;tu|du;ew|han/hon;em|vi;hûn|ni;dayik|mamma;bav|pappa;bira|bror;xwişk|syster;malbat|familj;nav|namn;zarok|barn;heval|vän;jin|kvinna;mêr|man;mezin|stor;piçûk|liten;baş|bra;erê|ja;na|nej','Navê min William e.|Jag heter William.;Tu çawa yî?|Hur mår du?;Ez baş im.|Jag mår bra.;Ev dayika min e.|Det här är min mamma.;Ev bavê min e.|Det här är min pappa.;Ew birayê min e.|Han är min bror.;Ew xwişka min e.|Hon är min syster.'),
('Hemma','mal|hem/hus;ode|rum;derî|dörr;pace|fönster;mase|bord;kursî|stol;nivîn|säng;pirtûk|bok;qelem|penna;cil|kläder;sol|skor;telefon|telefon;televîzyon|tv;mitbax|kök;hundir|inne;derve|ute;li vir|här;li wir|där;paş|bakom;pêş|framför','Ez li malê me.|Jag är hemma.;Pirtûka min li vir e.|Min bok är här.;Telefon li ku ye?|Var är telefonen?;Telefon li wir e.|Telefonen är där.;Ez li derve me.|Jag är ute.'),
('Mat och dryck','av|vatten;nan|bröd;şîr|mjölk;çay|te;sêv|äpple;moz|banan;hêk|ägg;goşt|kött;masî|fisk;penîr|ost;birinc|ris;şorbe|soppa;xwarin|äta/mat;vexwarin|dricka;birçî|hungrig;tî|törstig;xweş|god/trevlig;germ|varm;sar|kall;şîrîn|söt','Ez birçî me.|Jag är hungrig.;Ez tî me.|Jag är törstig.;Ez av dixwazim.|Jag vill ha vatten.;Ez sêv dixwim.|Jag äter ett äpple.;Ev xwarin pir xweş e!|Den här maten är jättegod!'),
('Kroppen och kläder','ser|huvud;çav|öga;guh|öra;dev|mun;poz|näsa;dest|hand;tilî|finger;ling|ben/fot;por|hår;diran|tand;rû|ansikte;çîp|axel;kiras|skjorta/klänning;pantolon|byxor;sol|skor;çorap|strumpor;çepik|mössa/keps;reş|svart;spî|vit;sor|röd','Ev destê min e.|Det här är min hand.;Du çavên min hene.|Jag har två ögon.;Porê min reş e.|Mitt hår är svart.;Solên min li ku ne?|Var är mina skor?'),
('Skolan','dibistan|skola;mamoste|lärare;şagirt|elev;ders|lektion;pirtûk|bok;defter|skrivhäfte;qelem|penna;çente|väska;mase|bord;kursî|stol;heval|vän;nivîsandin|skriva;xwendin|läsa/studera;pirs|fråga;bersiv|svar;rast|rätt;şaş|fel;hêsan|lätt;zor|svårt;ziman|språk','Ez diçim dibistanê.|Jag går till skolan.;Ev pirtûka min e.|Det här är min bok.;Ez dixwînim.|Jag läser.;Ez dinivîsim.|Jag skriver.;Ev hêsan e.|Det här är lätt.;Ev zor e.|Det här är svårt.'),
('Saker jag gör','çûn|gå/åka;hatin|komma;xwarin|äta;vexwarin|dricka;dîtin|se;gotin|säga;kirin|göra;lîstin|leka/spela;xwendin|läsa;nivîsandin|skriva;razan|sova;rûniştin|sitta;rabûn|resa sig/vakna;bezîn|springa;kenîn|skratta;girîn|gråta;zanîn|veta;xwestin|vilja;hezkirin|tycka om;axivîn|prata','Ez diçim malê.|Jag går hem.;Ez nan dixwim.|Jag äter bröd.;Ez av vedixwim.|Jag dricker vatten.;Ez dilîzim.|Jag leker/spelar.;Ez nizanim.|Jag vet inte.;Ez kurdî diaxivim.|Jag pratar kurdiska.'),
('Känslor','şad|glad;xemgîn|ledsen;westiyayî|trött;birçî|hungrig;tî|törstig;baş|bra;nexweş|sjuk;tirsiya|rädd;aciz|irriterad;bêzar|uttråkad;xweş|trevlig;hez|tycke;evîn|kärlek;kêfxweş|glad/nöjd;aram|lugn;pir|mycket;kêm|lite;hinek|lite/några;niha|nu;îro|idag','Ez şad im.|Jag är glad.;Ez westiyayî me.|Jag är trött.;Ez birçî me.|Jag är hungrig.;Tu çawa yî?|Hur mår du?;Ez îro baş im.|Jag mår bra idag.'),
('Siffror och tid','yek|ett;du|två;sê|tre;çar|fyra;pênc|fem;şeş|sex;heft|sju;heşt|åtta;neh|nio;deh|tio;îro|idag;sibê|imorgon;duh|igår;sibeh|morgon;şev|kväll/natt;roj|dag;hefte|vecka;meh|månad;sal|år;saet|klocka/timme','Ez neh salî me.|Jag är nio år.;Îro roja baş e.|Idag är en bra dag.;Ez sibê diçim dibistanê.|Jag går till skolan imorgon.;Saet çend e?|Vad är klockan?'),
('Frågor och samtal','çi|vad;kî|vem;ku|var;çima|varför;çawa|hur;kengî|när;çend|hur många;kîjan|vilken;erê|ja;na|nej;belkî|kanske;rast|rätt/sant;baş e|okej;spas|tack;silav|hej;xatirê te|hej då;bibore|ursäkta;dîsa|igen;hêdî|långsamt;zû|snabbt/tidigt','Ev çi ye?|Vad är det här?;Ew kî ye?|Vem är det?;Tu li ku yî?|Var är du?;Çima?|Varför?;Dîsa bêje.|Säg det igen.;Hêdî biaxive.|Prata långsamt.'),
('Jag använder kurmanji','kurdî|kurdiska;swêdî|svenska;ziman|språk;peyiv|ord;hevok|mening;pirs|fråga;bersiv|svar;famkirin|förstå;zanîn|veta;axivîn|prata;guhdarîkirin|lyssna;gotin|säga;dîsa|igen;hêdî|långsamt;hinek|lite;pir|mycket;rast|rätt;şaş|fel;alîkarî|hjälp;spas|tack','Ez hinek kurdî dizanim.|Jag kan lite kurdiska.;Ez kurdî hîn dibim.|Jag lär mig kurdiska.;Ez fam nakim.|Jag förstår inte.;Dîsa bêje.|Säg det igen.;Hêdî biaxive.|Prata långsamt.;Ev bi kurdî çi ye?|Vad heter det här på kurdiska?')]
data=[]
for i,(name,words,sentences) in enumerate(units,1):
 w=[dict(ku=a,sv=b) for a,b in (pair.split('|') for pair in words.split(';'))]
 s=[dict(ku=a,sv=b) for a,b in (pair.split('|') for pair in sentences.split(';'))]
 assert len(w)==20,(i,len(w))
 data.append(dict(id=i,title=name,words=w,sentences=s))
with open('/mnt/data/william-kurmanji-app/data.json','w',encoding='utf8') as f:json.dump(data,f,ensure_ascii=False,indent=2)
print('units',len(data),'word slots',sum(len(x['words']) for x in data),'unique',len(set(w['ku'] for u in data for w in u['words'])))
